for(int h=0;h<MaritimeLegend.Tests.TestData.Int("DomainChecks","simulationDays")*MaritimeLegend.Tests.TestData.Int("DomainChecks","hoursPerDay");h++){g.MarketHour();foreach(var cs in s.cities)foreach(var m in cs.market)if(m.stock<0||m.stock>c.market.maxStock)throw new Exception("NPC bounds");}Check(true,"30 game days / 720 NPC hourly replenishment cycles; stocks bounded");Check(g.Quote(0,timber,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),true)<g.Quote(MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"),timber,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),false),"cross-port raw trade has positive gross margin");
