SaveStore.TestDirectory=Path.GetFullPath("Temp/MaritimeTests/Saves");SaveStore.Save(s);var disk=SaveStore.Load(s.slot);Check(disk.orders.Last().quality==s.orders.Last().quality&&disk.gold==s.gold,"disk save hash and state roundtrip");SaveStore.Save(s);string path=SaveStore.PathFor(s.slot);File.WriteAllText(path,File.ReadAllText(path).Replace("\"hash\":\"","\"hash\":\"damaged"));bool refused=false;try{SaveStore.Load(s.slot);}catch{refused=true;}Check(refused,"corrupt save rejected without reset");Check(SaveStore.Load(s.slot,false,true).gold==s.gold,"backup recovery preserves state");SaveStore.TestDirectory=null;
Directory.CreateDirectory("Documentation");File.WriteAllLines("Documentation/TestResults.txt",lines.Concat(new[]{"TOTAL "+count+" checks passed", "These are deterministic rule simulations, not manual full UI acceptance or audio listening."}));Debug.Log("MARITIME_DOMAIN_TESTS_PASS "+count);
