static void Sail(GameService g,int to){string msg=g.Depart(to);if(!g.S.atSea)throw new Exception(msg);int steps=0;while(g.DistanceToPort()>MaritimeLegend.Tests.TestData.Double("DomainChecks","parameter27")&&steps++<MaritimeLegend.Tests.TestData.Int("DomainChecks","maxSteps")){var p=g.C.ports[to];g.S.heading=Math.Atan2(p.y-g.S.seaY,p.x-g.S.seaX);g.Sail(MaritimeLegend.Tests.TestData.Double("DomainChecks","parameter28"),1);g.Tick(MaritimeLegend.Tests.TestData.Double("DomainChecks","parameter28"),false);}if(steps>=MaritimeLegend.Tests.TestData.Int("DomainChecks","maxSteps"))throw new Exception("sailing timeout");g.Arrive();}
static void Campaign(Catalog c,string mode){var s=GameService.New(c,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),0,mode,new Appearance(),"Campaign",MaritimeLegend.Tests.TestData.UInt("DomainChecks","campaignSeed"));s.gold=MaritimeLegend.Tests.TestData.Int("DomainChecks","startingGold");var g=new GameService(c,s);string wood=c.Named("原木").id;g.Trade(0,wood,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),MaritimeLegend.Tests.TestData.Int("DomainChecks","parameter18"),true,s.cargo);g.Build(MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"));g.Inventory.Transfer(s.cargo,s.cities[0].warehouse,wood,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),MaritimeLegend.Tests.TestData.Int("DomainChecks","parameter18"));g.Start("r"+c.Named("木板").id,0);g.Advance(MaritimeLegend.Tests.TestData.Int("DomainChecks","productionAdvanceSeconds"),false);g.Claim(s.orders.Last().id);Sail(g,1);Check(s.chapter==MaritimeLegend.Tests.TestData.Int("DomainChecks","highQuality"),mode+" campaign chapter1 reached using production/trade/sailing");g.License();for(int i=0;i<MaritimeLegend.Tests.TestData.Int("DomainChecks","parameter31");i++){g.Trade(1,c.Named("小麦").id,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),1,true,s.cargo);}Sail(g,0);g.Recruit(0);
// Earn expedition funds through bounded raw cargo transfers, no money injection.
for(int loop=0;loop<MaritimeLegend.Tests.TestData.Int("DomainChecks","repeatCount")&&s.gold<MaritimeLegend.Tests.TestData.Int("DomainChecks","fundingTarget");loop++){int n=Math.Min(MaritimeLegend.Tests.TestData.Int("DomainChecks","simulationDays"),Math.Max(1,(s.gold-MaritimeLegend.Tests.TestData.Int("DomainChecks","repeatCount"))/MaritimeLegend.Tests.TestData.Int("DomainChecks","parameter34")));var export=c.ports[0].raw.OrderByDescending(id=>g.Preview(MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"),id,MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"),n,false)-g.Preview(0,id,MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"),n,true)).First();if(g.Preview(MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"),export,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),n,false)<=g.Preview(0,export,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),n,true)){for(int h=0;h<MaritimeLegend.Tests.TestData.Int("DomainChecks","parameter35");h++)g.MarketHour();continue;}int previousGold=s.gold;g.Trade(0,export,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),n,true,s.cargo);Sail(g,MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"));g.Trade(MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"),export,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),n,false,s.cargo);if(!s.cities[MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality")].license&&s.gold>MaritimeLegend.Tests.TestData.Int("DomainChecks","parameter36"))g.License();Sail(g,0);g.Supply();for(int h=0;h<MaritimeLegend.Tests.TestData.Int("DomainChecks","parameter35");h++)g.MarketHour();}lines.Add(mode+" campaign earned gold through adaptive raw trading: "+s.gold);

for(int i=0;i<MaritimeLegend.Tests.TestData.Int("DomainChecks","highQuality");i++){g.Start("r"+c.Named("木板").id,0);g.Advance(MaritimeLegend.Tests.TestData.Int("DomainChecks","productionAdvanceSeconds"),false);g.Claim(s.orders.Last().id);}g.CheckQuest();Check(s.chapter==MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"),mode+" campaign chapter2 reached with three licensed cities and partner");g.TrainPartner(0);g.BuyShip(1);Check(s.ships.Count>1,mode+" campaign can afford trade brig");g.Flagship(1);
// Craft terminal goods with genuinely purchased materials; all quality rolls use persisted PRNG.
EnsureFactory(g,MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"));CraftQuality(g,"木板",MaritimeLegend.Tests.TestData.Int("DomainChecks","highQuality"));MoveOne(g,"木板",MaritimeLegend.Tests.TestData.Int("DomainChecks","highQuality"));Sail(g,1);EnsureFactory(g,MaritimeLegend.Tests.TestData.Int("DomainChecks","highQuality"));CraftQuality(g,"布匹",MaritimeLegend.Tests.TestData.Int("DomainChecks","highQuality"));MoveOne(g,"布匹",MaritimeLegend.Tests.TestData.Int("DomainChecks","highQuality"));Check(g.SubmitMaterials().Contains("已登记"),mode+" distinct-port quality materials accepted");EnsureFactory(g,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"));CraftQuality(g,"旗舰航海仪",MaritimeLegend.Tests.TestData.Int("DomainChecks","highQuality"));EnsureFactory(g,MaritimeLegend.Tests.TestData.Int("DomainChecks","highQuality"));CraftQuality(g,"船帆",MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"));Check(s.instrumentMade&&s.sailsMade,mode+" campaign terminal manufactured goods reachable");Check(g.BeginFinal().Contains("解缆"),mode+" final gate satisfied");int steps=0;while(g.DistanceToPort()>MaritimeLegend.Tests.TestData.Double("DomainChecks","parameter27")&&steps++<MaritimeLegend.Tests.TestData.Int("DomainChecks","maxSteps")){var p=c.ports[MaritimeLegend.Tests.TestData.Int("DomainChecks","parameter37")];s.heading=Math.Atan2(p.y-s.seaY,p.x-s.seaX);g.Sail(MaritimeLegend.Tests.TestData.Double("DomainChecks","parameter28"),1);g.Tick(MaritimeLegend.Tests.TestData.Double("DomainChecks","parameter28"),false);}g.Arrive();Check(s.city==MaritimeLegend.Tests.TestData.Int("DomainChecks","parameter37")&&s.ships[0].food>MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality")&&s.ships[0].hull>MaritimeLegend.Tests.TestData.Int("DomainChecks","parameter18"),mode+" final voyage arrives with supplies");if(mode=="休闲"){g.Finish();Check(s.ended,"casual ending state and postgame unlocked");int reward=s.gold;g.Finish();Check(s.gold==reward,"ending reward cannot be claimed twice");}else lines.Add("CLASSIC: final battle UI still requires runtime combat acceptance; campaign gates tested only.");}
static void EnsureFactory(GameService g,int industry){if(g.S.cities[g.S.city].factories[industry]==0){string msg=g.Build(industry);if(g.S.cities[g.S.city].factories[industry]==0)throw new Exception("Factory "+msg);}}
static void CraftQuality(GameService g,string name,int maximum){var p=g.C.Named(name);var r=g.C.recipes.First(x=>x.output==p.id);EnsureFactory(g,r.industry);for(int attempt=0;attempt<MaritimeLegend.Tests.TestData.Int("DomainChecks","repeatCount");attempt++){foreach(var input in r.inputs){int need=input.quantity-g.Inventory.Count(g.S.cities[g.S.city].warehouse,input.product);if(need>0){var prod=g.C.Product(input.product);if(g.Market(g.S.city,prod.id).stock<need){if(prod.category=="R"){int port=g.C.ports.First(x=>x.raw.Contains(prod.id)).id;int home=g.S.city;Sail(g,port);g.Trade(port,prod.id,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),need,true,g.S.cargo);Sail(g,home);g.Inventory.Transfer(g.S.cargo,g.S.cities[home].warehouse,prod.id,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"),need);}else CraftQuality(g,prod.name,MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"));}else g.Trade(g.S.city,prod.id,prod.category=="R"?MaritimeLegend.Tests.TestData.Int("DomainChecks","lowQuality"):MaritimeLegend.Tests.TestData.Int("DomainChecks","standardQuality"),need,true,g.S.cities[g.S.city].warehouse);}}
int prev=g.S.orders.Count;string start=g.Start(r.id,g.S.city);if(g.S.orders.Count==prev)throw new Exception("Craft "+name+": "+start+" gold="+g.S.gold);g.Advance(MaritimeLegend.Tests.TestData.Int("DomainChecks","productionAdvanceSeconds"),false);var o=g.S.orders.Last();g.Claim(o.id);if(o.quality<=maximum)return;}throw new Exception("Quality target not reached "+name);}
static void MoveOne(GameService g,string name,int maximum){var inv=g.S.cities[g.S.city].warehouse;var b=inv.batches.First(x=>x.product==g.C.Named(name).id&&x.quality<=maximum);g.Inventory.Transfer(inv,g.S.cargo,b.product,b.quality,1);}
